def convert_rates(apps, schema_editor):
    """Old rate types become a plain rate per piece (owner, 19 Oct 2026): plus add-ons keeps its base rate,
    size-wise takes its most common size rate, a flat amount per lot cannot be converted and is switched off
    to be re-entered."""
    from collections import Counter

    LabourRate = apps.get_model("jobwork", "LabourRate")
    Size = apps.get_model("jobwork", "LabourRateSize")
    report = []
    for r in LabourRate.objects.all():
        if r.rate_type == "C":
            amounts = Counter(Size.objects.filter(rate_id=r.pk).values_list("amount", flat=True))
            r.rate = amounts.most_common(1)[0][0] if amounts else r.base_rate
            report.append(f"size-wise rate {r.pk} now {r.rate} per piece")
        elif r.rate_type == "D":
            r.rate = r.base_rate
            r.is_active = False
            report.append(f"flat-per-lot rate {r.pk} ({r.flat_amount} per lot) switched off: re-enter it on Rates")
        else:
            r.rate = r.base_rate
            if r.rate_type == "B":
                report.append(f"rate {r.pk} plus add-ons now {r.rate} per piece (add-ons dropped)")
        r.save(update_fields=["rate", "is_active"])
    for line in report:
        print(f"  Rates: {line}")


